//! Required real first-user/native/config producers on both migrated engines.
use axum::{body::{Body,to_bytes},http::{Request,StatusCode}};
use serde_json::{json,Value};use sqlx::{AnyPool,Connection,Column,Row};use tower::ServiceExt;
use std::{path::{Path,PathBuf},collections::BTreeMap,io::Read};use sha2::{Digest,Sha256};
const JWT:&str="owned-password-fixture-secret";const PASSWORD:&str="owned-fixture-password-not-a-real-account";
fn workspace()->PathBuf{PathBuf::from(std::env::var("STARLANE_NATIVE_WORKSPACE").expect("required owned native workspace"))}
async fn pool(url:&str,schema:&str)->AnyPool{sqlx::any::install_default_drivers();let engine=crate::db::DatabaseEngine::from_url(url).unwrap();let schema=schema.to_owned();sqlx::any::AnyPoolOptions::new().max_connections(3).after_connect(move|c,_|{let schema=schema.clone();Box::pin(async move{match engine{crate::db::DatabaseEngine::Postgres=>{sqlx::query(&format!("SET search_path TO {schema}")).execute(c).await?;},crate::db::DatabaseEngine::Sqlite=>{sqlx::query("PRAGMA foreign_keys=ON").execute(&mut*c).await?;sqlx::query("PRAGMA busy_timeout=5000").execute(c).await?;}}Ok(())})}).connect(url).await.unwrap()}
fn state(db:AnyPool,root:&Path)->crate::AppState{crate::AppState{db,jwt_secret:JWT.into(),base_url:"http://owned.invalid".into(),search_index:crate::search::SearchIndex::new(root.join("search_index")).unwrap(),oauth_cache:crate::auth::routes::OAuthStateCache::new(),ws_rooms:crate::sync::WsRooms::default()}}

async fn call(s:&crate::AppState,token:Option<&str>,method:&str,uri:&str,body:Value)->(StatusCode,Value){println!("NATIVE_STEP {method} {uri}");let mut q=Request::builder().method(method).uri(uri).header("Content-Type","application/json");if let Some(t)=token{q=q.header("Authorization",format!("Bearer {t}"));}let mut req=q.body(Body::from(body.to_string())).unwrap();req.extensions_mut().insert(axum::extract::ConnectInfo("127.0.0.1:43123".parse::<std::net::SocketAddr>().unwrap()));let r=crate::api_routes().with_state(s.clone()).oneshot(req).await.unwrap();let code=r.status();let bytes=to_bytes(r.into_body(),4*1024*1024).await.unwrap();(code,if bytes.is_empty(){Value::Null}else{serde_json::from_slice(&bytes).unwrap_or(json!({"non_json":true}))})}
async fn ok(s:&crate::AppState,token:Option<&str>,method:&str,uri:&str,body:Value)->Value{let(code,v)=call(s,token,method,uri,body).await;assert!(code.is_success(),"actual {method} {uri} status={code}; response suppressed to protect credentials");v}
fn access(v:&Value)->&str{v["access_token"].as_str().unwrap()}fn refresh(v:&Value)->&str{v["refresh_token"].as_str().unwrap()}fn sid(v:&Value)->String{crate::auth::jwt::validate_token(access(v),JWT,crate::auth::jwt::TokenType::Access).unwrap().sid}
async fn snapshot(db:&AnyPool,tables:&[&str])->BTreeMap<String,Vec<Value>>{let mut out=BTreeMap::new();for table in tables{let mut values=Vec::new();for row in sqlx::query(&format!("SELECT * FROM {table}")).fetch_all(db).await.unwrap(){let mut cells=BTreeMap::new();for col in row.columns(){let n=col.name();let v=if let Ok(v)=row.try_get::<Option<String>,_>(n){v.map(|v|json!(["text",v])).unwrap_or(json!(["null"]))}else if let Ok(v)=row.try_get::<Option<i64>,_>(n){v.map(|v|json!(["integer",v.to_string()])).unwrap_or(json!(["null"]))}else if let Ok(v)=row.try_get::<Option<Vec<u8>>,_>(n){v.map(|v|json!(["blob",hex::encode(v)])).unwrap_or(json!(["null"]))}else{panic!("unsupported cell {table}.{n}")};cells.insert(n.to_string(),v);}values.push(serde_json::to_value(cells).unwrap());}values.sort_by_cached_key(Value::to_string);out.insert(table.to_string(),values);}out}
fn login_body(email:&str,password:&str)->Value{json!({"email":email,"password":password,"device_name":"Owned browser","session_kind":"browser","client_platform":"web"})}
fn bytes(root:&Path)->BTreeMap<String,String>{fn walk(root:&Path,p:&Path,out:&mut BTreeMap<String,String>){let m=std::fs::symlink_metadata(p).unwrap();assert!(!m.file_type().is_symlink());if m.is_dir(){for e in std::fs::read_dir(p).unwrap(){walk(root,&e.unwrap().path(),out);}}else{assert!(m.is_file());let mut f=std::fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0u8;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}out.insert(p.strip_prefix(root).unwrap().to_string_lossy().into(),hex::encode(h.finalize()));}}let mut out=BTreeMap::new();for n in["spaces",".storage-journal",".publication-journal",".canonical-rewrite-journal",".move-relocation-journal"]{let p=root.join(n);if p.exists(){walk(root,&p,&mut out);}}out}


const EMAIL:&str="native-owner@owned.invalid";
fn exchange_body(id:&str,verifier:&str)->Value{json!({"handoff_id":id,"code_verifier":verifier,"session_kind":"app","client_platform":"desktop_app","device_name":"Owned native"})}
fn pkce()->(String,String){let(c,v)=oauth2::PkceCodeChallenge::new_random_sha256();(c.as_str().into(),v.secret().into())}
async fn start(s:&crate::AppState)->(String,String){let(c,v)=pkce();let x=ok(s,None,"POST","/auth/native-handoff/start",json!({"code_challenge":c})).await;let id=x["handoff_id"].as_str().unwrap().to_owned();assert_eq!(x["authorization_url"],format!("http://owned.invalid/app-signin/?handoff_id={id}"));(id,v)}
async fn approve(s:&crate::AppState,a:&Value,id:&str){let x=ok(s,Some(access(a)),"POST","/auth/native-handoff/complete",json!({"handoff_id":id})).await;assert_eq!(x["status"],"approved");assert_eq!(x["handoff_id"],id);}
async fn exchange(s:&crate::AppState,id:&str,v:&str)->(StatusCode,Value){call(s,None,"POST","/auth/native-handoff/exchange",exchange_body(id,v)).await}
const DOMAIN:&[&str]=&["users","sessions","native_auth_handoffs","spaces","space_members","documents","document_drafts","storage_journal_receipts","system_config","audit_log"];
async fn domain(s:&crate::AppState)->BTreeMap<String,Vec<Value>>{snapshot(&s.db,DOMAIN).await}
async fn denied(s:&crate::AppState,id:&str,v:&str){let b=domain(s).await;let f=bytes(&crate::storage::data_dir());assert_eq!(exchange(s,id,v).await.0,StatusCode::UNAUTHORIZED);assert!(b==domain(s).await,"denied exchange changed authoritative records");assert_eq!(f,bytes(&crate::storage::data_dir()));}
async fn failure(s:&crate::AppState,engine:&str,id:&str,v:&str,kind:&str){let before=domain(s).await;let files=bytes(&crate::storage::data_dir());let table=if kind=="sessionrollback"{"sessions"}else{"native_auth_handoffs"};let event=if kind=="sessionrollback"{"INSERT"}else{"UPDATE"};let when=if kind=="sessionrollback"{"AFTER"}else{"BEFORE"};if engine=="sqlite"{sqlx::query(&format!("CREATE TRIGGER native_fail {when} {event} ON {table} BEGIN SELECT RAISE(ABORT,'owned native failure'); END")).execute(&s.db).await.unwrap();}else{sqlx::query("CREATE FUNCTION native_fail_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'owned native failure'; END $$").execute(&s.db).await.unwrap();sqlx::query(&format!("CREATE TRIGGER native_fail {when} {event} ON {table} FOR EACH ROW EXECUTE FUNCTION native_fail_fn()")).execute(&s.db).await.unwrap();}assert_eq!(exchange(s,id,v).await.0,StatusCode::INTERNAL_SERVER_ERROR);assert!(before==domain(s).await,"failed native exchange consumed handoff or partially changed sessions");assert_eq!(files,bytes(&crate::storage::data_dir()));if engine=="sqlite"{sqlx::query("DROP TRIGGER native_fail").execute(&s.db).await.unwrap();}else{sqlx::query(&format!("DROP TRIGGER native_fail ON {table}")).execute(&s.db).await.unwrap();sqlx::query("DROP FUNCTION native_fail_fn()").execute(&s.db).await.unwrap();}println!("NATIVE_REAL_CONSTITUENT_ROLLBACK_PASS {kind}");}
async fn contended(s:crate::AppState,id:String,v:String,n:std::sync::Arc<tokio::sync::Notify>)->(StatusCode,Value){let f:Box<dyn FnOnce()+Send>=Box::new(move||n.notify_one());crate::auth::routes::NATIVE_BEFORE_FENCE_SIGNAL.scope(std::cell::RefCell::new(Some(f)),exchange(&s,&id,&v)).await}
async fn wait_activity(s:&crate::AppState,uid:&str,id:&str,v:&str){let mut held=s.db.begin().await.unwrap();crate::spaces::mutation_guards::lock_audience_for_mutation(&mut held).await.unwrap();sqlx::query("UPDATE users SET is_active=0 WHERE id=$1").bind(uid).execute(&mut*held).await.unwrap();let b=snapshot(&s.db,&["sessions","native_auth_handoffs"]).await;let n=std::sync::Arc::new(tokio::sync::Notify::new());let mut task=tokio::spawn(contended(s.clone(),id.into(),v.into(),n.clone()));tokio::time::timeout(std::time::Duration::from_secs(5),n.notified()).await.unwrap();assert!(tokio::time::timeout(std::time::Duration::from_millis(50),&mut task).await.is_err(),"exchange did not wait for held lifecycle fence");held.commit().await.unwrap();assert_eq!(task.await.unwrap().0,StatusCode::UNAUTHORIZED);assert!(b==snapshot(&s.db,&["sessions","native_auth_handoffs"]).await);sqlx::query("UPDATE users SET is_active=1 WHERE id=$1").bind(uid).execute(&s.db).await.unwrap();println!("NATIVE_REAL_ACTIVITY_WAIT_PASS");}
async fn journey(s:&crate::AppState,engine:&str,kind:&str)->Value{let a=ok(s,None,"POST","/auth/register",json!({"email":EMAIL,"display_name":"Native owner","password":PASSWORD,"device_name":"Owned registration"})).await;let login=ok(s,None,"POST","/auth/login",login_body(EMAIL,PASSWORD)).await;assert_eq!(login["user"]["id"],a["user"]["id"]);let uid=a["user"]["id"].as_str().unwrap();let space:String=sqlx::query_scalar("SELECT id FROM spaces WHERE created_by=$1").bind(uid).fetch_one(&s.db).await.unwrap();let q=ok(s,Some(access(&login)),"POST",&format!("/spaces/{space}/documents"),json!({"source_id":"native-page","title":"Native exact page","content":"EXACT_NATIVE_PAGE Ω","property_values":[]})).await;ok(s,Some(access(&login)),"POST",&format!("/spaces/{space}/documents/native-page/drafts/{}/publish",q["draft_id"].as_str().unwrap()),json!({})).await;
let(id,v)=start(s).await;let before=domain(s).await;let pending=exchange(s,&id,&v).await;assert_eq!(pending.0,StatusCode::ACCEPTED);assert_eq!(pending.1["status"],"pending");assert!(before==domain(s).await);denied(s,&id,&"x".repeat(43)).await;denied(s,&id,"short").await;let b=domain(s).await;assert_eq!(call(s,None,"POST","/auth/native-handoff/complete",json!({"handoff_id":id})).await.0,StatusCode::UNAUTHORIZED);assert!(b==domain(s).await);approve(s,&login,&id).await;
if matches!(kind,"sessionrollback"|"handoffrollback"){failure(s,engine,&id,&v,kind).await;}if kind=="inactive"{sqlx::query("UPDATE users SET is_active=0 WHERE id=$1").bind(uid).execute(&s.db).await.unwrap();denied(s,&id,&v).await;sqlx::query("UPDATE users SET is_active=1 WHERE id=$1").bind(uid).execute(&s.db).await.unwrap();println!("NATIVE_REAL_ACTIVITY_DENIAL_PASS");}if kind=="activitywait"{wait_activity(s,uid,&id,&v).await;}
let existing=snapshot(&s.db,&["sessions"]).await["sessions"].len();let native=if kind=="concurrency"{let(s1,s2)=(s.clone(),s.clone());let(i1,i2)=(id.clone(),id.clone());let(v1,v2)=(v.clone(),v.clone());let (a,b)=tokio::join!(tokio::spawn(async move{exchange(&s1,&i1,&v1).await}),tokio::spawn(async move{exchange(&s2,&i2,&v2).await}));let(a,b)=(a.unwrap(),b.unwrap());assert!((a.0==StatusCode::OK&&b.0==StatusCode::UNAUTHORIZED)||(b.0==StatusCode::OK&&a.0==StatusCode::UNAUTHORIZED));println!("NATIVE_REAL_ONE_EXCHANGE_PASS");if a.0==StatusCode::OK{a.1}else{b.1}}else{ok(s,None,"POST","/auth/native-handoff/exchange",exchange_body(&id,&v)).await};assert_eq!(native["user"]["id"],uid);assert_eq!(snapshot(&s.db,&["sessions"]).await["sessions"].len(),existing+1);let metadata:(String,String,String,String)=sqlx::query_as("SELECT user_id,session_kind,client_platform,device_name FROM sessions WHERE id=$1").bind(sid(&native)).fetch_one(&s.db).await.unwrap();assert_eq!(metadata,(uid.into(),"app".into(),"desktop_app".into(),"Owned native".into()));denied(s,&id,&v).await;
let (expired,ev)=start(s).await;approve(s,&login,&expired).await;sqlx::query("UPDATE native_auth_handoffs SET expires_at='2000-01-01T00:00:00Z' WHERE id=$1").bind(&expired).execute(&s.db).await.unwrap();denied(s,&expired,&ev).await;
let me=ok(s,Some(access(&native)),"GET","/auth/me",Value::Null).await;assert_eq!(me["id"],uid);let files=bytes(&crate::storage::data_dir());assert!(!files.is_empty());let stable=snapshot(&s.db,&["users","spaces","space_members","documents","document_drafts","storage_journal_receipts","native_auth_handoffs"]).await;println!("NATIVE_ACTUAL_PRODUCER_BYTES_PASS {kind}");json!({"native":native,"space":space,"stable":stable,"files":files})}
async fn run(engine:&str,kind:&str){let root=crate::storage::data_dir();assert!(root.starts_with(workspace()));let url=if engine=="postgres"{std::env::var("STARLANE_NATIVE_PG_URL").expect("required owned PG URL")}else{format!("sqlite://{}?mode=rwc",root.join("starlane-notes.db").display())};std::fs::create_dir_all(&root).unwrap();let schema=if engine=="postgres"{sqlx::any::install_default_drivers();let name=format!("native_{}",uuid::Uuid::new_v4().simple());let mut c=sqlx::AnyConnection::connect(&url).await.unwrap();sqlx::query(&format!("CREATE SCHEMA {name}")).execute(&mut c).await.unwrap();c.close().await.unwrap();name}else{String::new()};let db=pool(&url,&schema).await;crate::db::migrate_selected(&db,crate::db::DatabaseEngine::from_url(&url).unwrap()).await.unwrap();let s=state(db,&root);let e=journey(&s,engine,kind).await;std::fs::write(workspace().join("expected.json"),e.to_string()).unwrap();s.db.close().await;drop(s);let child=std::process::Command::new(std::env::current_exe().unwrap()).args(["postgres_native_fixture::fresh_native_child","--ignored","--exact","--nocapture"]).env("STARLANE_NATIVE_CHILD_URL",url).env("STARLANE_NATIVE_SCHEMA",schema).output().unwrap();assert!(child.status.success(),"{}\n{}",String::from_utf8_lossy(&child.stdout),String::from_utf8_lossy(&child.stderr));println!("NATIVE_FRESH_CHILD {}",String::from_utf8_lossy(&child.stdout));}
macro_rules! case{($name:ident,$engine:literal,$kind:literal)=>{#[tokio::test]#[ignore="required owned native handoff orchestration"]async fn $name(){run($engine,$kind).await;}};}
case!(required_postgres_flow,"postgres","flow");case!(required_sqlite_flow,"sqlite","flow");
case!(required_postgres_sessionrollback,"postgres","sessionrollback");case!(required_sqlite_sessionrollback,"sqlite","sessionrollback");
case!(required_postgres_handoffrollback,"postgres","handoffrollback");case!(required_sqlite_handoffrollback,"sqlite","handoffrollback");
case!(required_postgres_inactive,"postgres","inactive");case!(required_sqlite_inactive,"sqlite","inactive");
case!(required_postgres_activitywait,"postgres","activitywait");case!(required_sqlite_activitywait,"sqlite","activitywait");
case!(required_postgres_concurrency,"postgres","concurrency");case!(required_sqlite_concurrency,"sqlite","concurrency");
#[tokio::test]#[ignore="only genuine native parent launches"]async fn fresh_native_child(){let url=std::env::var("STARLANE_NATIVE_CHILD_URL").expect("required native parent URL");let schema=std::env::var("STARLANE_NATIVE_SCHEMA").expect("required parent schema");let root=crate::storage::data_dir();assert!(root.starts_with(workspace()));let e:Value=serde_json::from_slice(&std::fs::read(workspace().join("expected.json")).unwrap()).unwrap();let s=state(pool(&url,&schema).await,&root);assert_eq!(serde_json::to_value(snapshot(&s.db,&["users","spaces","space_members","documents","document_drafts","storage_journal_receipts","native_auth_handoffs"]).await).unwrap(),e["stable"]);crate::storage::restoration::bootstrap_gate(&root).unwrap();crate::storage::restoration::activate_in(&root,&s.db).await.unwrap();crate::storage::relocation::recover(&s.db).await.unwrap();crate::storage::journal::recover(&s.db).await.unwrap();crate::storage::canonical_rewrite::recover(&s.db).await.unwrap();crate::storage::publication::recover(&s.db).await.unwrap();crate::storage::attachment_upload::recover_in(&root,&s.db).await.unwrap();assert_eq!(serde_json::to_value(snapshot(&s.db,&["users","spaces","space_members","documents","document_drafts","storage_journal_receipts","native_auth_handoffs"]).await).unwrap(),e["stable"]);let me=ok(&s,Some(access(&e["native"])),"GET","/auth/me",Value::Null).await;assert_eq!(me["id"],e["native"]["user"]["id"]);let login=ok(&s,None,"POST","/auth/login",login_body(EMAIL,PASSWORD)).await;assert_eq!(login["user"]["id"],me["id"]);let content=ok(&s,Some(access(&login)),"GET",&format!("/spaces/{}/documents/native-page/content",e["space"].as_str().unwrap()),Value::Null).await;assert!(content["content"].as_str().unwrap().contains("EXACT_NATIVE_PAGE Ω"));assert_eq!(serde_json::to_value(bytes(&root)).unwrap(),e["files"]);s.db.close().await;drop(s);println!("NATIVE_ACTUAL_FRESH_RESTART_PASS");}
